// Hand-authored — NOT generated by prism, and prism will not overwrite it
// (it only replaces files carrying its header). See the React wrapper for the
// reasoning: virtualization is the one case where the wrapper has to own the
// rows, because only Angular can create an Angular row.
//
// Rows come from a template the consumer passes in, which is the Angular-native
// shape:
//
//   <arc-virtual-list [items]="rows" [rowTemplate]="row">
//     <ng-template #row let-item let-i="index">{{ item.name }}</ng-template>
//   </arc-virtual-list>
//
// The host element *is* the arc-virtual-list, so this component's template
// renders straight into its light DOM — which is exactly where slotted rows
// have to be.
import { NgTemplateOutlet } from '@angular/common';
import {
  Component, ElementRef, HostListener, Input, TemplateRef, inject, signal,
} from '@angular/core';
import { ArcVirtualList } from '@arclux/arc-ui/virtual-list';

@Component({
  selector: 'arc-virtual-list',
  standalone: true,
  imports: [NgTemplateOutlet],
  template: `
    @for (row of visible(); track row.index) {
      <div [attr.slot]="'item-' + row.index">
        <ng-container
          [ngTemplateOutlet]="rowTemplate"
          [ngTemplateOutletContext]="{ $implicit: row.item, index: row.index }"
        />
      </div>
    }
  `,
})
export class VirtualList {
  // `visibleRange` is a getter on the element; the generated .d.ts describes
  // properties, so it is spelled out here rather than assumed.
  private readonly _el: ArcVirtualList & {
    visibleRange?: { start: number; end: number };
  } = inject(ElementRef).nativeElement;

  /** Renders one row. Instantiated only for rows currently on screen. */
  @Input({ required: true }) rowTemplate!: TemplateRef<unknown>;

  private readonly _items = signal<unknown[]>([]);
  private readonly _range = signal({ start: 0, end: 0 });

  /** The full data array. Only the visible slice is rendered. */
  @Input() set items(value: unknown[]) {
    this._items.set(value ?? []);
    this._el.items = value ?? [];
    // The element measures against the new length; until it reports back, the
    // old range may point past the end.
    if (this._el.visibleRange) this._range.set({ ...this._el.visibleRange });
  }
  get items(): unknown[] {
    return this._items();
  }

  /** Row height in pixels. Must match what actually renders. */
  @Input() set itemHeight(value: number) {
    this._el.itemHeight = value;
  }
  get itemHeight(): number {
    return this._el.itemHeight;
  }

  /** Rows rendered above and below the viewport, to cover fast scrolling. */
  @Input() set overscan(value: number) {
    this._el.overscan = value;
  }
  get overscan(): number {
    return this._el.overscan;
  }

  @HostListener('arc-range-change', ['$event'])
  protected _onRangeChange(e: CustomEvent<{ start: number; end: number }>) {
    this._range.set({ start: e.detail.start, end: e.detail.end });
  }

  protected readonly visible = () => {
    const items = this._items();
    const { start, end } = this._range();
    const out: { item: unknown; index: number }[] = [];
    for (let i = start; i < Math.min(end, items.length); i++) {
      out.push({ item: items[i], index: i });
    }
    return out;
  };
}
